package atf.api.reporting;

/** Runtime controller for the diagnostic Fails projection and deep-links. */
final class ExtentReportFailureRuntime {
    private ExtentReportFailureRuntime() { }

    static String script() {
        return "function failedAssertionRows(item){return q('.helm-validation-table tbody tr',item).filter(function(row){var result=String(row.textContent||'').toLowerCase(),status=row.getAttribute('data-atf-assertion-status')||'';return status==='fail'||result.indexOf('❌')>=0||!!row.querySelector('.badge-danger');});}"
                + "function failureContextFor(item,anchor){var ctx=failureContext(item);if(!anchor)return ctx;var cells=Array.prototype.slice.call(anchor.cells||[]).map(function(cell){return text(cell,'');}),label=cells[0]||'Assertion',expected=cells[1]||'',actual=cells[2]||'';var validation=anchor.closest('.card');if(validation){var title=text(validation,'.card-title a.node');if(title)ctx.validation=title;}ctx.assertion=label+' → '+statusDisplay(expected)+' → '+statusDisplay(actual);ctx.message=label+' expected '+statusDisplay(expected)+', actual '+statusDisplay(actual);return ctx;}"
                + "function failureIndexMarkup(name,ctx,id,scenarioIndex,ordinal){return '<div class=\"atf-failure-index atf-failure-evidence\" data-atf-failure-id=\"failure-'+esc(id)+'-'+esc(scenarioIndex)+'-'+esc(ordinal||1)+'\"><h4 class=\"atf-failure-index-title\">'+esc(name)+'</h4><div class=\"atf-failure-index-row\"><span class=\"atf-failure-label\">TEST</span><span class=\"atf-failure-value\">'+esc(ctx.owner||'API tests')+'</span></div><div class=\"atf-failure-index-row\"><span class=\"atf-failure-label\">PHASE</span><span class=\"atf-failure-value\">'+esc(ctx.phase)+'</span></div><div class=\"atf-failure-index-row\"><span class=\"atf-failure-label\">REQUEST</span><span class=\"atf-failure-value\">'+esc(ctx.request)+'</span></div><div class=\"atf-failure-index-row\"><span class=\"atf-failure-label\">DURATION</span><span class=\"atf-failure-value\">'+esc(ctx.duration)+'</span></div><div class=\"atf-failure-index-row\"><span class=\"atf-failure-label\">VALIDATION</span><span class=\"atf-failure-value\">'+esc(ctx.validation)+'</span></div><div class=\"atf-failure-index-row\"><span class=\"atf-failure-label\">ASSERTION</span><span class=\"atf-failure-value\">'+esc(ctx.assertion)+'</span></div><div class=\"atf-failure-index-row atf-failure-index-cause\"><span class=\"atf-failure-label\">CAUSE</span><span class=\"atf-failure-value\">'+esc(ctx.message)+'</span></div><button type=\"button\" class=\"atf-failure-open\" title=\"Open the exact failing test in the Tests tab\" data-atf-test-id=\"'+esc(id)+'\" data-atf-scenario-index=\"'+esc(scenarioIndex)+'\" data-atf-failure-ordinal=\"'+esc(ordinal||1)+'\">Open in Tests</button></div>'; }"
                + "function selectFailure(index){var rows=q('#atf-failure-list>.test-item'),row=rows[index],detail=document.getElementById('atf-failure-detail');if(!row||!detail)return;for(var i=0;i<rows.length;i++)rows[i].classList.toggle('active',i===index);var id=row.getAttribute('data-atf-test-id'),scenarioIndex=row.getAttribute('data-atf-scenario-index');detail.innerHTML='';var indexMarkup=row.getAttribute('data-atf-index-html')||'';if(indexMarkup)detail.insertAdjacentHTML('beforeend',indexMarkup);var open=detail.querySelector('.atf-failure-open');if(open)open.addEventListener('click',function(e){e.preventDefault();atfOpenTest(id,scenarioIndex);});}"
                + "function renderFails(){var host=document.getElementById('atf-failure-list');if(!host)return;var records=[];testItems().filter(function(item){return statusOf(item)==='fail';}).forEach(function(item){var failedRows=failedAssertionRows(item);if(!failedRows.length)failedRows=[null];failedRows.forEach(function(assertionRow,ordinal){records.push({item:item,assertionRow:assertionRow,ordinal:ordinal+1});});});host.innerHTML='';var detail=document.getElementById('atf-failure-detail');if(detail)detail.innerHTML='';if(!records.length){host.innerHTML='<div class=\"atf-fails-empty\">No failed tests.</div>';return;}records.forEach(function(record,index){var item=record.item,id=item.getAttribute('data-atf-class-root-id')||item.getAttribute('test-id'),scenarioIndex=item.getAttribute('data-atf-scenario-index')||'0',name=testName(item),owner=testClass(item),ctx=failureContextFor(item,record.assertionRow);ctx.owner=owner;var row=document.createElement('div');row.className='test-item atf-failure';row.setAttribute('status','fail');row.setAttribute('data-atf-test-id',id);row.setAttribute('data-atf-scenario-index',scenarioIndex);row.setAttribute('data-atf-failure-ordinal',String(record.ordinal));row.setAttribute('data-atf-failure-id','failure-'+id+'-'+scenarioIndex+'-'+record.ordinal);row.setAttribute('data-atf-failure-phase',ctx.phase);row.setAttribute('data-atf-index-html',failureIndexMarkup(name,owner,ctx,id,scenarioIndex,record.ordinal));row.innerHTML='<div class=\"test-detail\"><p class=\"name\">'+esc(name)+'</p><p class=\"text-sm\">'+esc(owner)+'</p></div><div class=\"test-status\"><span class=\"badge log badge-danger\">Fail</span></div>';row.addEventListener('click',function(){selectFailure(index);});host.appendChild(row);});selectFailure(0);}"
                + "renderFails=function(){var host=document.getElementById('atf-failure-list');if(!host)return;var records=[];testItems().filter(function(item){return statusOf(item)==='fail';}).forEach(function(item){var failedRows=failedAssertionRows(item);if(!failedRows.length)failedRows=[null];failedRows.forEach(function(assertionRow,ordinal){records.push({item:item,assertionRow:assertionRow,ordinal:ordinal+1});});});var phaseOrder={'SETUP':0,'TEST BODY':1,'TEARDOWN':2};records.sort(function(a,b){var ap=failureContextFor(a.item,a.assertionRow).phase,bp=failureContextFor(b.item,b.assertionRow).phase;return (phaseOrder[ap]===undefined?99:phaseOrder[ap])-(phaseOrder[bp]===undefined?99:phaseOrder[bp]);});host.innerHTML='';var detail=document.getElementById('atf-failure-detail');if(detail)detail.innerHTML='';if(!records.length){host.innerHTML='<div class=\"atf-fails-empty\">No failed tests.</div>';return;}records.forEach(function(record,index){var item=record.item,id=item.getAttribute('data-atf-class-root-id')||item.getAttribute('test-id'),scenarioIndex=item.getAttribute('data-atf-scenario-index')||'0',name=testName(item),owner=testClass(item),ctx=failureContextFor(item,record.assertionRow);ctx.owner=owner;var row=document.createElement('div');row.className='test-item atf-failure';row.setAttribute('status','fail');row.setAttribute('data-atf-test-id',id);row.setAttribute('data-atf-scenario-index',scenarioIndex);row.setAttribute('data-atf-failure-ordinal',String(record.ordinal));row.setAttribute('data-atf-failure-id','failure-'+id+'-'+scenarioIndex+'-'+record.ordinal);row.setAttribute('data-atf-failure-phase',ctx.phase);row.setAttribute('data-atf-index-html',failureIndexMarkup(name,ctx,id,scenarioIndex,record.ordinal));row.innerHTML='<div class=\"test-detail\"><p class=\"name\">'+esc(name)+'</p><p class=\"text-sm\">'+esc(owner)+'</p></div><div class=\"test-status\"><span class=\"badge log badge-danger\">Fail</span></div>';row.addEventListener('click',function(){selectFailure(index);});host.appendChild(row);});selectFailure(0);};";
    }
}
